create table if not exists users (id serial primary key, email text unique not null, password_hash text not null, created_at timestamptz default now());
create table if not exists watchlist (id serial primary key, user_id int not null references users(id) on delete cascade, symbol text not null, name text, country text, unique(user_id, symbol));
create table if not exists alerts (id serial primary key, user_id int not null references users(id) on delete cascade, symbol text not null, target numeric not null, direction text not null, triggered boolean default false, created_at timestamptz default now());
